// Pharmacy Science Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: drug classes by disorder, counseling points,
// compounding technique and pharmacy calculations.
import {q, mix} from './q.js';
const ASHP='Bachenheimer & Phillips, Manual for Pharmacy Technicians (ASHP)', STU='Stuhan, Understanding Pharmacology for Pharmacy Technicians', ABB='Drugs.com prescription abbreviations';
const HIST='Pharmacy Practice History & Practice Settings', LAW='Pharmacy Law & Ethics and Safety & Infection Control', TERM='Pharmacy Terminology & Abbreviations', FORM='Dosage Formulations & Administration Routes', COMP='Sterile and Non-Sterile Compounding', CONC='Concentration & Dilutions', DIS='Disorders & Treatments';

export default {
 id:'pharmacy-science-1',
 event:'Pharmacy Science',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'ASHP’s Manual for Pharmacy Technicians, Stuhan’s Understanding Pharmacology for Pharmacy Technicians, and Drugs.com abbreviations',
 plan:[{area:HIST,weight:4},{area:LAW,weight:10},{area:TERM,weight:10},{area:FORM,weight:10},{area:COMP,weight:10},{area:CONC,weight:10},{area:DIS,weight:46}],
 questions:mix([
  q(HIST,'In which practice setting do pharmacy technicians most often prepare sterile IV admixtures?','Hospital pharmacy',['Community retail pharmacy','Mail-order pharmacy','Nuclear medicine clinic'],'B','Hospitals supply IV medications for inpatients, so institutional pharmacies have cleanrooms and technicians trained in sterile compounding.',ASHP),
  q(HIST,'Long-term care pharmacies commonly supply medications in which packaging?','Unit-dose packages',['Large stock bottles','Paper envelopes','Bulk powders'],'D','Unit-dose and blister packaging lets nursing facilities give the right dose at the right time and track each dose, reducing errors.',ASHP),
  q(LAW,'Which 1951 amendment created the legal distinction between prescription and over-the-counter drugs?','Durham-Humphrey Amendment',['Kefauver-Harris Amendment','Orphan Drug Act','Harrison Narcotic Act'],'A','The Durham-Humphrey Amendment defined drugs that require a prescription (“legend” drugs) and allowed oral and refill prescriptions.',ASHP),
  q(LAW,'After the thalidomide tragedy, which 1962 law required drug makers to prove effectiveness as well as safety?','Kefauver-Harris Amendment',['Durham-Humphrey Amendment','Pure Food and Drug Act','Controlled Substances Act'],'C','The Kefauver-Harris Amendment required proof of efficacy before approval and strengthened rules for clinical trials and informed consent.',ASHP),
  q(LAW,'Which law requires most prescription drugs to be dispensed in child-resistant containers?','Poison Prevention Packaging Act',['Food, Drug, and Cosmetic Act','HIPAA','Drug Listing Act'],'B','The Poison Prevention Packaging Act of 1970 requires child-resistant packaging unless the patient or prescriber requests otherwise or the drug is exempt (such as sublingual nitroglycerin).',ASHP),
  q(LAW,'Under the Combat Methamphetamine Epidemic Act, what must pharmacies do when selling pseudoephedrine?','Keep it behind the counter and log purchases',['Require a prescription for every sale','Sell it only to people over 65','Sell it only in liquid form'],'D','Pseudoephedrine can be used to make methamphetamine. Sales are limited by quantity, products are kept behind the counter, and buyers show ID and sign a log.',ASHP),
  q(LAW,'Chemotherapy drugs are hazardous. Where should they be compounded?','In a biological safety cabinet',['On an open counter','In a horizontal laminar airflow hood','In the patient’s room'],'A','Hazardous drugs are prepared in a vertical-flow biological safety cabinet or isolator that protects the worker and the environment, following USP <800>.',ASHP),
  q(TERM,'What does the sig “1 tab po bid pc” mean?','Take 1 tablet by mouth twice daily after meals',['Take 1 tablet by mouth twice daily before meals','Take 1 tablet by mouth at bedtime','Take 1 tablet under the tongue as needed'],'C','po = by mouth, bid = twice daily, pc = after meals. ac means before meals, hs means at bedtime, and SL means sublingual.',ABB),
  q(TERM,'What does NKDA mean on a patient profile?','No known drug allergies',['No known drug addiction','Not kept due to allergy','New kind of drug administered'],'B','NKDA tells the pharmacy the patient reports no medication allergies. Allergies must be checked before every prescription is filled.',ABB),
  q(TERM,'What does “OU” mean on an eye drop prescription?','Both eyes',['Right eye','Left eye','Both ears'],'D','OU = both eyes, OD = right eye, OS = left eye. Because AU, AD and AS (ears) look similar, many facilities require these to be written out.',ABB),
  q(TERM,'A prescription reads “2 tabs po tid × 10 days.” How many tablets should be dispensed?','60 tablets',['20 tablets','30 tablets','40 tablets'],'A','tid = three times daily. 2 tablets × 3 times a day × 10 days = 60 tablets.',ABB),
  q(TERM,'What does the first segment of a National Drug Code (NDC) identify?','The labeler',['The drug’s strength','The package size','The expiration date'],'C','The NDC has three segments: labeler, product (drug, strength, form) and package size.',ASHP),
  q(FORM,'Why should extended-release (ER or XR) tablets not be crushed?','Crushing can release the whole dose at once',['Crushing makes them taste better','Crushed tablets cannot be swallowed','Crushing changes the drug’s name'],'B','Extended-release forms are designed to release the drug slowly. Crushing them can cause dangerous peaks in drug levels.',STU),
  q(FORM,'What counseling point applies to an oral suspension?','Shake well before each use',['Do not shake the bottle','Store it in the freezer','Take it only on an empty stomach'],'D','In a suspension, solid drug particles settle over time. Shaking redistributes them so each dose is correct.',STU),
  q(FORM,'A patient who is vomiting cannot keep oral medications down. Which dosage form may be useful?','Rectal suppository',['Enteric-coated tablet','Extended-release capsule','Chewable tablet'],'A','Suppositories are absorbed through the rectal mucosa, avoiding the stomach and partly bypassing first-pass metabolism.',STU),
  q(FORM,'A patient asks whether ear drops can be used in the eye. What is correct?','No; only ophthalmic products are made for the eye',['Yes; otic and ophthalmic drops are the same','Yes, if the dose is cut in half','No, unless they are warmed first'],'C','Ophthalmic products are sterile and pH-adjusted for the eye. Otic (ear) products may not be sterile and can irritate or damage the eye.',STU),
  q(FORM,'Which route places a drug between the cheek and gum to be absorbed?','Buccal',['Sublingual','Transdermal','Intradermal'],'B','Buccal products dissolve against the cheek. Sublingual products go under the tongue, and transdermal products are absorbed through the skin.',STU),
  q(COMP,'In a laminar airflow workbench, how far inside the hood should sterile manipulations be performed?','At least 6 inches',['At the front edge','1 inch','Outside the hood'],'D','Working at least 6 inches inside keeps critical sites in first air, the HEPA-filtered air that has not touched any object.',ASHP),
  q(COMP,'Which item is put on last when garbing for sterile compounding?','Sterile gloves',['Shoe covers','Hair cover','Face mask'],'A','Garbing goes from dirtiest to cleanest: shoe covers, hair and facial hair covers, mask, hand hygiene, gown, and finally sterile gloves inside the buffer area.',ASHP),
  q(COMP,'Which technique evenly mixes a small amount of a potent drug into a large amount of base?','Geometric mixing',['Spatulation','Levigation','Sifting'],'C','In geometric dilution, the drug is mixed with an equal amount of base, then that mixture with an equal amount of base, and so on, ensuring even distribution.',ASHP),
  q(COMP,'Grinding a solid into a fine powder with a mortar and pestle is called:','Trituration',['Levigation','Sublimation','Filtration'],'B','Trituration reduces particle size by grinding. Levigation reduces particle size by rubbing the powder with a small amount of liquid to form a paste.',ASHP),
  q(COMP,'How does a beyond-use date differ from a manufacturer’s expiration date?','It applies after compounding or repackaging',['It is always later than the expiration date','It is set by the patient','It applies only to over-the-counter drugs'],'D','The beyond-use date is assigned by the pharmacy after compounding or repackaging and is usually much shorter than the manufacturer’s expiration date.',ASHP),
  q(CONC,'What is the percent strength of a solution with 2 g of drug in 100 mL?','2%',['0.2%','20%','50%'],'A','Percent weight in volume is grams per 100 mL, so 2 g in 100 mL is 2%.',ASHP),
  q(CONC,'50 mL of a 20% solution is diluted to 10%. What is the final volume?','100 mL',['25 mL','75 mL','200 mL'],'C','C1V1 = C2V2: 20% × 50 mL = 10% × V2, so V2 = 100 mL. Add 50 mL of diluent.',ASHP),
  q(CONC,'A solution is labeled 1:1000. What is its percent strength?','0.1%',['1%','0.01%','10%'],'B','1:1000 means 1 g in 1000 mL, which equals 0.1 g in 100 mL, or 0.1%. Ratio strengths are common for epinephrine.',ASHP),
  q(CONC,'An oral suspension contains 250 mg/5 mL. How many mL are needed for a 375 mg dose?','7.5 mL',['3.3 mL','6 mL','15 mL'],'D','Desired ÷ have × quantity: 375 mg ÷ 250 mg × 5 mL = 1.5 × 5 = 7.5 mL. An oral syringe gives the most accurate measurement.',ASHP),
  q(CONC,'Using alligation, how many grams of 20% ointment are needed to make 500 g of 10% ointment by mixing with 5% ointment?','167 g',['100 g','250 g','333 g'],'A','20% gets 10 − 5 = 5 parts and 5% gets 20 − 10 = 10 parts (15 total). 5/15 × 500 g = 166.7 g, about 167 g of the 20% ointment.',ASHP),
  q(DIS,'Losartan and valsartan, used for hypertension, belong to which drug class?','Angiotensin receptor blockers',['ACE inhibitors','Beta blockers','Calcium channel blockers (CCBs)'],'C','Drugs ending in -sartan block angiotensin II receptors. Unlike ACE inhibitors (-pril), they rarely cause a dry cough.',STU),
  q(DIS,'A patient taking atorvastatin should report which side effect promptly?','Unexplained muscle pain',['A single mild headache','Slight change in taste','Increased appetite'],'B','Statins can rarely cause muscle damage (myopathy or rhabdomyolysis), which can harm the kidneys.',STU),
  q(DIS,'How does apixaban prevent clots?','It inhibits clotting factor Xa',['It blocks vitamin K','It dissolves existing clots','It stops platelets from forming'],'D','Apixaban and rivaroxaban (-xaban) directly inhibit factor Xa. Unlike warfarin, they do not require routine INR monitoring.',STU),
  q(DIS,'How should sublingual nitroglycerin tablets be stored?','In the original glass bottle',['In a plastic pill organizer','In the refrigerator in a paper bag','In a warm car for quick access'],'A','Nitroglycerin loses potency with exposure to air, light, heat and moisture, so it stays in its original amber glass bottle.',STU),
  q(DIS,'A patient taking digoxin reports nausea and seeing yellow-green halos around lights. What may this indicate?','Digoxin toxicity',['A normal side effect','An allergic reaction','Too little digoxin'],'C','Visual changes, nausea, confusion and irregular heartbeat are classic signs of digoxin toxicity, often linked to low potassium.',STU),
  q(DIS,'Why should patients rinse their mouths after using an inhaled corticosteroid such as fluticasone?','To prevent oral thrush',['To make the drug work faster','To prevent a dry cough','To improve the taste of food'],'B','Steroid residue in the mouth can allow yeast to grow. Rinsing and spitting reduces the risk of oropharyngeal candidiasis.',STU),
  q(DIS,'Which inhaler is used as a rescue medication for sudden asthma symptoms?','Albuterol',['Fluticasone','Montelukast','Salmeterol'],'D','Albuterol is a short-acting beta-2 agonist that opens airways within minutes. Fluticasone and montelukast are controllers, and salmeterol is long-acting.',STU),
  q(DIS,'Tiotropium is used for COPD. How does it work?','It blocks acetylcholine to keep airways open',['It reduces airway inflammation as a steroid','It thins mucus in the airways','It stimulates breathing in the brain'],'A','Tiotropium is a long-acting anticholinergic (muscarinic antagonist) that prevents airway narrowing. It is a maintenance drug, not a rescue inhaler.',STU),
  q(DIS,'Which insulin is long-acting and provides a steady basal level for about 24 hours?','Insulin glargine',['Insulin lispro','Regular insulin','NPH insulin'],'C','Glargine (Lantus, Basaglar) has no pronounced peak. Lispro is rapid-acting for mealtimes, regular is short-acting, and NPH is intermediate-acting.',STU),
  q(DIS,'Why is metformin used cautiously in patients with poor kidney function?','It increases the risk of lactic acidosis',['It causes severe low blood sugar','It damages the liver quickly','It raises blood pressure'],'B','Metformin is cleared by the kidneys. If it builds up, it can cause lactic acidosis, a rare but serious complication.',STU),
  q(DIS,'Which drug treats hyperthyroidism by reducing thyroid hormone production?','Methimazole',['Levothyroxine','Liothyronine','Calcitonin'],'D','Methimazole blocks thyroid hormone synthesis. Levothyroxine and liothyronine replace thyroid hormone in hypothyroidism.',STU),
  q(DIS,'When should omeprazole usually be taken?','30–60 minutes before breakfast',['Right after a large meal','At bedtime with a snack','Only when heartburn starts'],'A','Proton pump inhibitors work best when taken before a meal, when acid pumps are being activated.',STU),
  q(DIS,'Which side effect of opioid pain medications does not lessen with continued use?','Constipation',['Drowsiness','Nausea','Itching'],'C','Tolerance develops to sedation and nausea, but not to constipation, so patients on long-term opioids often need a bowel regimen.',STU),
  q(DIS,'Why should ibuprofen be taken with food or milk?','To protect the stomach lining',['To make it work faster','To prevent drowsiness','To increase how much is absorbed'],'B','NSAIDs block prostaglandins that protect the stomach lining, which can cause irritation, ulcers and bleeding.',STU),
  q(DIS,'How does allopurinol prevent gout attacks?','It lowers uric acid production',['It relieves acute joint pain','It increases calcium absorption','It dissolves kidney stones of any type'],'D','Allopurinol inhibits xanthine oxidase, reducing uric acid production. It is used for prevention, not to treat an acute attack.',STU),
  q(DIS,'Which counseling point applies to alendronate for osteoporosis?','Take with plain water and stay upright',['Take with a glass of milk at bedtime','Crush the tablet into applesauce','Lie down right after taking it'],'A','Alendronate can irritate the esophagus. It is taken on an empty stomach in the morning with plain water, and the patient remains upright.',STU),
  q(DIS,'A patient starting fluoxetine asks when it will help. What is typical?','Full benefit may take 4 to 6 weeks',['It works within 1 hour','It works only on the first day','It never takes more than 3 days'],'C','SSRIs need several weeks to reach full effect. Patients should not stop them suddenly and should report worsening mood or suicidal thoughts.',STU),
  q(DIS,'Methylphenidate for ADHD is in which DEA schedule?','Schedule II',['Schedule I','Schedule IV','Schedule V'],'B','Stimulants have a high potential for abuse with accepted medical use, so they are Schedule II and cannot be refilled; a new prescription is needed.',ASHP),
  q(DIS,'Which side effect is associated with long-term phenytoin use?','Gum overgrowth',['Hair loss','Hearing loss','Weight loss'],'D','Phenytoin can cause gingival hyperplasia, so good oral hygiene is important. It also has a narrow therapeutic range.',STU),
  q(DIS,'Why is carbidopa combined with levodopa for Parkinson’s disease?','It keeps levodopa from breaking down early',['It replaces dopamine in the brain directly','It blocks acetylcholine','It treats the tremor only'],'A','Carbidopa blocks peripheral breakdown of levodopa, so more reaches the brain (where it becomes dopamine) and nausea is reduced.',STU),
  q(DIS,'A patient asks for an antibiotic for a cold. Why is this not appropriate?','They do not work on viruses',['They work too slowly for colds','Colds are caused by fungi','Antibiotics cause colds'],'C','Colds are viral. Unnecessary antibiotics cause side effects and contribute to antibiotic resistance.',STU),
  q(DIS,'For the best effect, when should oseltamivir be started for influenza?','Within 48 hours of symptom onset',['After 7 days of symptoms','Only after a fever breaks','Before any flu exposure, once a year'],'B','Oseltamivir works best when started within 2 days of symptoms, shortening illness. The yearly flu vaccine is the main form of prevention.',STU),
  q(DIS,'Why are loratadine and cetirizine often preferred over diphenhydramine for allergies?','They cause less drowsiness',['They work only at night','They also treat infections','They are controlled substances'],'D','Second-generation antihistamines cross the blood-brain barrier less, so they are less sedating than first-generation drugs like diphenhydramine.',STU)
 ],79)
};
